VFT-C1.code:
@layer components {
  .status-badge {
    display: inline-flex;
    align-items: center;
    padding-block: var(--shelf-badge-paddingBlock);
    padding-inline: var(--shelf-badge-paddingInline);
    border-radius: var(--shelf-badge-radius);
    border: 1px solid var(--shelf-badge-borderColor);
    font-size: var(--shelf-badge-fontSize);
    font-weight: 600;
    line-height: 1;
    white-space: nowrap;
  }

  .status-badge[data-status="reading"] {
    background-color: var(--shelf-badge-bgColor-reading);
    color: var(--shelf-badge-fgColor-reading);
  }

  .status-badge[data-status="finished"] {
    background-color: var(--shelf-badge-bgColor-finished);
    color: var(--shelf-badge-fgColor-finished);
  }

  .status-badge[data-status="want-to-read"] {
    background-color: var(--shelf-badge-bgColor-want-to-read);
    color: var(--shelf-badge-fgColor-want-to-read);
  }
}
